regimes={'nosov-sun-city-needs-machinery':2,'nova-praxis-apostate-exclusion':3,'lancer-thirdcomm-metropolitan-core':2,'dyson-program-virtual-homeland':1,'per-aspera-supplied-martian-colonies':5,'oa-sophic-automation-contemplation':5,'oa-technorapture-affiliate-environments':5,'twinmaker-household-fabber-abundance':2,'riverworld-common-grail-access':1,'suffadv-first-edition-stardweller-basics':2}
for rid,updates,paragraph,facts in rows:
 old=D['societies'][rid];r=deepcopy(old);refs=r['source_ids']
 assert all(r['axis'][k] is None for k in updates),rid
 for key,(value,bounds,basis) in updates.items():r['axis'][key]=value;r['axis_assessment'][key]=assessment(value,bounds,'low',basis,refs)
 r['description']=old['description'].split('\n\n')[0]+'\n\n'+paragraph
 r.update(assessment_mode='best_guess',best_guess_axes=list(updates),qualification_basis='Earlier bounded evidence-based inclusion retained; individually supply the remaining coordinate scenarios under the current user policy.',qualification_confidence='low',canon_facts=facts,editorial_assumptions=[v[2] for v in updates.values()])
 r['uncertainties']=[u for u in old['uncertainties'] if not any(t in u.lower() for t in ['remains unresolved','stays unresolved','cannot be considered complete','requires a separate editorial estimate'])]
 r['uncertainties']+=['New coordinate values are low-confidence editorial scenarios, not canonical statistics; original source limits remain.']+r['editorial_assumptions']
 if rid in regimes and r['record_type']!='zero_variant':
  primary=regimes[rid];prior=r['regime_primary'];r['regime_primary']=primary;r['regime_alternatives']=sorted((set(r['regime_alternatives'])|{prior})-{primary})
 r['review'].update(date=DATE,coordinate_ready=True,method='Individual completion against existing bounded evidence, with explicit active-person and useful-work scenarios; no independent reviewer or new full-work reading')
 assert all(v is not None for v in r['axis'].values()),rid
 assert len(r['description'].split())>=110,rid
 changes.append(change(D,'societies',r))
write_revision(18,changes,'Finish the twenty-seven remaining retained-coordinate gaps. Rights, practical control and useful work receive separate estimates; every previously retained record now has three numeric coordinates without claiming canonical censuses.')
